-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_VODAFONE.SNOWBOTS.T_CLOSE_SENTINEL
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/London'
  CONFIG = '{"autonomy": 3}'
  WHEN SYSTEM$STREAM_HAS_DATA('SDP_VODAFONE.PUBLIC.STR_GL_JOURNAL')
AS
  CALL SDP_VODAFONE.SNOWBOTS.SP_RUN_BOT('close-sentinel');

-- step 1 · Actuals landed: October SAP + billing
SELECT SYSTEM$STREAM_HAS_DATA('SDP_VODAFONE.PUBLIC.STR_GL_JOURNAL') OR SYSTEM$STREAM_HAS_DATA('SDP_VODAFONE.PUBLIC.STR_BILLING');
-- step 2 · Completeness DMFs per feed
SELECT feed, SNOWFLAKE.CORE.ROW_COUNT(...) AS rows_loaded, expected_rows,
       rows_loaded / expected_rows AS completeness
FROM SDP_VODAFONE.SNOWBOTS.V_FEED_EXPECTATIONS WHERE period = '2026-10';
-- step 3 · Fallback: revenue from SAP ACDOCA for the late billing feed
CALL SDP_VODAFONE.SNOWBOTS.SP_BACKFILL_FROM_ACDOCA('BRIM_DE', '2026-10');
-- step 4 · Reconcile: billing ↔ SAP revenue + intercompany
CALL SDP_VODAFONE.SNOWBOTS.SP_RECONCILE(period => '2026-10', tolerance_pct => 0.2);
-- step 5 · Guardrail: completeness ≥ 99% and TB difference = 0
SELECT MIN(completeness) >= 0.99 AND ABS(SUM(tb_diff)) = 0 FROM SDP_VODAFONE.SNOWBOTS.V_CLOSE_STATUS WHERE period = '2026-10';
-- step 6 · Lock period 2026-10 (awaiting CFO approval)
CALL SDP_VODAFONE.PUBLIC.SP_LOCK_PERIOD('2026-10', approved_by => :approver);

