-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_VODAFONE.SNOWBOTS.T_DRIVER_REFRESH
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/London'
  CONFIG = '{"autonomy": 4}'
AS
  CALL SDP_VODAFONE.SNOWBOTS.SP_RUN_BOT('driver-refresh');

-- step 1 · Marketplace share refreshed
SELECT MAX(date) FROM ENERGY_MARKETPLACE.PUBLIC.POWER_PRICES_DAILY;
-- step 2 · Upsert energy and FX drivers
MERGE INTO SDP_VODAFONE.PUBLIC.DIM_DRIVER t USING (SELECT * FROM ENERGY_MARKETPLACE.PUBLIC.POWER_PRICES_DAILY WHERE date = CURRENT_DATE - 1) s ON t.driver = s.market ...;
-- step 3 · Guardrail: daily move ≤ 5%
SELECT MAX(ABS(pct_change)) <= 0.05 FROM SDP_VODAFONE.SNOWBOTS.V_DRIVER_MOVES;
-- step 4 · Recalculate network energy cost Nov–Mar
CALL SDP_VODAFONE.PUBLIC.SP_RECALC(scope => 'NETWORK_ENERGY', from_period => '2026-11');
-- step 5 · One-line impact note
SELECT AI_COMPLETE('claude-sonnet-4-5', 'One sentence on: ' || :impact_json);

